import copy, hashlib, json, pathlib, subprocess, tempfile, yaml
BASE=pathlib.Path.cwd()
def call(args, cwd):
 return subprocess.run(args,cwd=cwd,text=True,capture_output=True,timeout=12)
def render(values=None, valid=True, release='trial', namespace='training'):
 with tempfile.TemporaryDirectory(prefix='opsforge-s05-helm-') as td:
  root=pathlib.Path(td)
  for name in MATERIAL:
   p=root/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text((BASE/name).read_text())
  if values is not None:(root/'values.yaml').write_text(yaml.safe_dump(values))
  p=call(['helm','template',release,'.','--namespace',namespace,'--kube-version','1.34.1'],root)
  assert (p.returncode==0)==valid, p.stdout+p.stderr
  if not valid:return []
  lint=call(['helm','lint','.'],root);assert lint.returncode==0,lint.stdout+lint.stderr
  docs=[d for d in yaml.safe_load_all(p.stdout) if d is not None]
  assert all(isinstance(d,dict) for d in docs)
  assert len({(d['kind'],d['metadata'].get('namespace'),d['metadata']['name']) for d in docs})==len(docs)
  return docs
def unchanged():
 for name,digest in FIXED.items():
  assert hashlib.sha256((BASE/name).read_bytes()).hexdigest()==digest,'fixed material changed: '+name
 actual={p.as_posix() for p in pathlib.Path('templates').rglob('*') if p.is_file()}
 assert actual=={n for n in MATERIAL if n.startswith('templates/')},'extra templates'
unchanged()
base=json.loads(pathlib.Path('values.yaml').read_text())
for env,secret,public,replicas in [('dev','',False,1),('prod','approved-a',False,3),('prod','approved-b',True,0)]:
 v={**base,'environment':env,'existingSecret':secret,'public':public,'replicas':replicas}
 docs=render(v,release='safe');assert {d['kind'] for d in docs}=={'Service','Deployment'} and len(docs)==2
 s=next(d for d in docs if d['kind']=='Service');d=next(d for d in docs if d['kind']=='Deployment')
 assert s['spec']['type']==('LoadBalancer' if public else 'ClusterIP')
 assert s['metadata']=={'name':'safe','namespace':'training'} and d['metadata']==s['metadata']
 assert s['spec']['selector']==d['spec']['selector']['matchLabels']==d['spec']['template']['metadata']['labels']=={'app':'safe'}
 pod=d['spec']['template']['spec'];c=pod['containers'][0]
 assert d['spec']['replicas']==replicas and pod['automountServiceAccountToken'] is False and pod['securityContext']['runAsNonRoot'] is True
 assert c['readinessProbe']['httpGet']=={'path':'/ready','port':'http'}
 assert c['resources']=={'requests':{'cpu':'50m','memory':'32Mi'},'limits':{'cpu':'200m','memory':'128Mi'}}
 assert c.get('envFrom',[])==([{'secretRef':{'name':secret}}] if secret else [])
for patch in [{'environment':'prod'}, {'public':'false'}, {'replicas':-1}, {'environment':'staging'}, {'rawTemplate':'anything'}]:render({**base,**patch},valid=False)

