import math
def assess(deployment, quota, terminating):
 s=deployment['spec'];n=s['replicas'];r=s['strategy']['rollingUpdate']
 def amount(x,up):
  return (math.ceil if up else math.floor)(n*int(x[:-1])/100) if isinstance(x,str) else x
 surge=amount(r['maxSurge'],True);unavailable=amount(r['maxUnavailable'],False)
 pod=s['template']['spec']
 def quantity(text,key):
  if key=='cpu':return int(text[:-1]) if text.endswith('m') else int(text)*1000
  if text.endswith('Gi'):return int(text[:-2])*1024
  if text.endswith('Mi'):return int(text[:-2])
  raise ValueError('only Mi or Gi memory')
 per={}
 for key in ('cpu','memory'):
  app=sum(quantity(c['resources']['requests'][key],key) for c in pod['containers'])
  init=max([quantity(c['resources']['requests'][key],key) for c in pod.get('initContainers',[])]+[0])
  per[key]=max(app,init)
 peak=n+surge+terminating
 need={'pods':peak,'cpu_m':peak*per['cpu'],'memory_mi':peak*per['memory']}
 return {'surge':surge,'unavailable':unavailable,'minimum_available':n-unavailable,'need':need,'allowed':all(need[k]<=quota[k] for k in need)}


