import hashlib, re, yaml
def inventory(manifest,external):
 docs=[d for d in yaml.safe_load_all(manifest) if d]
 images=set();refs=set()
 for d in docs:
  p=d['spec']['template']['spec']
  for c in p.get('containers',[])+p.get('initContainers',[]):
   image=c['image']
   if not re.fullmatch(r'[^ @]+@sha256:[0-9a-f]{64}',image):raise ValueError('mutable image')
   images.add(image)
   for env in c.get('envFrom',[]):
    for kind in ('configMapRef','secretRef'):
     if kind in env:refs.add(('ConfigMap' if kind=='configMapRef' else 'Secret',d['metadata']['namespace'],env[kind]['name']))
