 if current['spec']==approved['spec']:return current
 patch=[{'op':'test','path':'/metadata/uid','value':expected_uid},{'op':'test','path':'/metadata/resourceVersion','value':current['metadata']['resourceVersion']},{'op':'replace','path':'/spec','value':copy.deepcopy(approved['spec'])}]
