from urllib.parse import quote,urlencode
def mapping(request,namespace,name):
 def get(path):
  code,obj=request('GET',path)
  if code==403:raise PermissionError('read forbidden')
  if code!=200:raise RuntimeError('read failed')
  return obj
 ns=quote(namespace,safe='');svc=get('/api/v1/namespaces/'+ns+'/services/'+quote(name,safe=''));uid=svc['metadata']['uid'];slices=[];token=''
 while True:
  query={'labelSelector':'kubernetes.io/service-name='+name,'limit':1}
  if token:query['continue']=token
  page=get('/apis/discovery.k8s.io/v1/namespaces/'+ns+'/endpointslices?'+urlencode(query))
  slices.extend(o for o in page['items'] if any(r.get('kind')=='Service' and r.get('uid')==uid for r in o['metadata'].get('ownerReferences',[])))
  token=page['metadata'].get('continue','')
  if not token:break
 result=[]
 for p in svc['spec']['ports']:
  resolved=sorted({sp['port'] for o in slices for sp in (o.get('ports') or []) if sp.get('name','')==p.get('name','') and sp.get('protocol','TCP')==p.get('protocol','TCP') and sp.get('port') is not None})
  result.append({'name':p.get('name'),'protocol':p.get('protocol','TCP'),'service_port':p['port'],'target_port':p.get('targetPort',p['port']),'node_port':p.get('nodePort'),'resolved_endpoint_ports':resolved})
