package main
import("context";"crypto/tls";"crypto/x509";"errors";"fmt";"io";"net";"net/http";"os";"sort";"strconv";"time")
type Runtime struct{Resolver,Name,CAFile string;Port int}
type Client struct{runtime Runtime;policy Policy;resolver *net.Resolver;roots *x509.CertPool;addresses []string;refreshed time.Time}
func NewClient(runtime Runtime,p Policy)(*Client,error){
 if runtime.Resolver==""||runtime.Name==""||runtime.Port<1||runtime.Port>65535{return nil,fmt.Errorf("explicit DNS/name/port required")}
 pem,e:=os.ReadFile(runtime.CAFile);if e!=nil{return nil,e};roots:=x509.NewCertPool();if !roots.AppendCertsFromPEM(pem){return nil,fmt.Errorf("invalid CA")}
 resolver:=&net.Resolver{PreferGo:true,Dial:func(ctx context.Context,network,address string)(net.Conn,error){return (&net.Dialer{}).DialContext(ctx,network,runtime.Resolver)}}
 return &Client{runtime:runtime,policy:p,resolver:resolver,roots:roots},nil
}
func unique(ips []net.IP)[]string{set:=map[string]bool{};for _,ip:=range ips{if ip.To4()!=nil{set[ip.String()]=true}};out:=[]string{};for ip:=range set{out=append(out,ip)};sort.Strings(out);return out}
func errorClass(e error)string{if errors.Is(e,context.DeadlineExceeded){return "timeout"};var cert *tls.CertificateVerificationError;if errors.As(e,&cert){return "tls_verification"};var ne net.Error;if errors.As(e,&ne)&&ne.Timeout(){return "timeout"};return "connection_error"}
func(c *Client)Fetch()(out Report){
 started:=time.Now();out=Report{StartedUnixNano:started.UnixNano(),DNS:[]DNSObservation{},Attempts:[]Attempt{},Pool:[]string{},Policy:c.policy,ServiceExistence:"unverified",DataPlaneVerified:false}
 defer func(){out.ElapsedMS=float64(time.Since(started))/float64(time.Millisecond);out.Pool=append([]string{},c.addresses...)}()
 ctx,cancel:=context.WithTimeout(context.Background(),time.Duration(c.policy.RequestTimeoutMS)*time.Millisecond);defer cancel()
 if len(c.addresses)==0||time.Since(c.refreshed)>=time.Duration(c.policy.RefreshMS)*time.Millisecond{
  at:=time.Now();lookupCtx,stop:=context.WithTimeout(ctx,time.Duration(c.policy.AttemptTimeoutMS)*time.Millisecond);ips,e:=c.resolver.LookupIP(lookupCtx,"ip4",c.runtime.Name+".");stop();event:=DNSObservation{AtUnixNano:at.UnixNano(),Addresses:[]string{}}
  if e!=nil{var dns *net.DNSError;if errors.As(e,&dns)&&dns.IsNotFound{event.ErrorClass="no_usable_answers";out.Outcome="no_usable_answers"}else{event.ErrorClass="resolver_unavailable";out.Outcome="resolver_unavailable"};out.DNS=append(out.DNS,event);return out}
  c.addresses=unique(ips);c.refreshed=time.Now();event.Addresses=append([]string{},c.addresses...);out.DNS=append(out.DNS,event)
  if len(c.addresses)==0{out.Outcome="no_usable_answers";return out}
 }
 for _,address:=range c.addresses{
  if ctx.Err()!=nil{out.Outcome="request_deadline";return out}
  at:=time.Now();attempt:=Attempt{Address:address,AtUnixNano:at.UnixNano()};attemptCtx,stop:=context.WithTimeout(ctx,time.Duration(c.policy.AttemptTimeoutMS)*time.Millisecond)
  transport:=&http.Transport{DisableKeepAlives:true,TLSClientConfig:&tls.Config{RootCAs:c.roots,ServerName:c.runtime.Name,MinVersion:tls.VersionTLS12},DialContext:func(ctx context.Context,network,destination string)(net.Conn,error){return (&net.Dialer{}).DialContext(ctx,network,net.JoinHostPort(address,strconv.Itoa(c.runtime.Port)))}}
  request,e:=http.NewRequestWithContext(attemptCtx,"GET","https://"+net.JoinHostPort(c.runtime.Name,strconv.Itoa(c.runtime.Port))+"/proof",nil)
  if e==nil{request.Host=c.runtime.Name;var response *http.Response;response,e=(&http.Client{Transport:transport}).Do(request);if e==nil{attempt.Status=response.StatusCode;var body []byte;body,e=io.ReadAll(io.LimitReader(response.Body,65536));response.Body.Close();if e==nil&&response.StatusCode==http.StatusOK{attempt.ElapsedMS=float64(time.Since(at))/float64(time.Millisecond);out.Attempts=append(out.Attempts,attempt);out.Outcome="success";out.SuccessAddress=address;out.Body=string(body);stop();transport.CloseIdleConnections();return out};if e==nil{attempt.ErrorClass="application_refused"}}}
  if e!=nil{attempt.ErrorClass=errorClass(e)};attempt.ElapsedMS=float64(time.Since(at))/float64(time.Millisecond);out.Attempts=append(out.Attempts,attempt);stop();transport.CloseIdleConnections()
 }
 if ctx.Err()!=nil{out.Outcome="request_deadline"}else{out.Outcome="members_exhausted"};return out
}

PLAN.md
# Headless client project
The real Go resolver dials the explicit native CoreDNS endpoint and returns members; DNS performs no application retry. This process owns member selection and unique-member failover. policy.json is parsed by policy.go; main.go is the persistent stdin CLI (one `fetch` line requests one operation), client.go performs actual DNS/TLS/HTTP, and audit.go emits per-operation native observations.

Refresh replaces membership after refresh_ms, including removal of retired members. New operations after a failed required refresh fail closed rather than use stale membership. Each new request uses a fresh connection and verified CA/hostname; this project does not claim established-connection draining. Each endpoint attempt and the complete operation have real timeouts.

The experiment origins are real fixed-student WSL host TLS/HTTP listeners on existing API-valid IPs. They are not running Pods, and no CNI, kube-proxy or Kubernetes Service forwarding capability is claimed. The original Pod-address question is exercised only for its client/discovery behavior condition; literal Pod runtime remains an independent-review boundary.

原始最低要求：客户端或其使用的协议库负责选择和重试，DNS只提供发现结果并受缓存影响。需明确地址刷新、超时及成员退役策略，不能假设Kubernetes会在同一个失败连接上自动替客户端换后端。

