package main
import "context"
type Policy struct{MaxAttempts int `json:"max_attempts"`;OverallDeadlineMS int `json:"overall_deadline_ms"`;AttemptTimeoutMS int `json:"attempt_timeout_ms"`;BaseBackoffMS int `json:"base_backoff_ms"`;MaxBackoffMS int `json:"max_backoff_ms"`;CacheWindowMS int `json:"cache_window_ms"`;MinRequestSpacingMS int `json:"min_request_spacing_ms"`}
type Config struct{Resolver,Name,CAFile string;Port int;Policy Policy}
type Runner interface{Fetch(context.Context)Report}
type Round struct{Index int `json:"index"`;AtUnixNano int64 `json:"at_unix_nano"`;DiscoveryClass string `json:"discovery_class"`;Addresses []string `json:"addresses"`;UsedCache bool `json:"used_cache"`;CacheAgeMS float64 `json:"cache_age_ms"`}
type Attempt struct{Round int `json:"round"`;Address string `json:"address"`;AtUnixNano int64 `json:"at_unix_nano"`;ElapsedMS float64 `json:"elapsed_ms"`;Status int `json:"status"`;ErrorClass string `json:"error_class,omitempty"`}
type Backoff struct{AtUnixNano int64 `json:"at_unix_nano"`;NominalMS float64 `json:"nominal_ms"`;Draw float64 `json:"draw"`;RequestedMS float64 `json:"requested_ms"`;ActualMS float64 `json:"actual_ms"`}
type Report struct{Sequence int `json:"sequence"`;StartedUnixNano int64 `json:"started_unix_nano"`;ElapsedMS float64 `json:"elapsed_ms"`;Outcome string `json:"outcome"`;StopReason string `json:"stop_reason"`;Rounds []Round `json:"rounds"`;Attempts []Attempt `json:"attempts"`;Backoffs []Backoff `json:"backoffs"`;RetryCount int `json:"retry_count"`;ErrorsByClass map[string]int `json:"errors_by_class"`;Pool []string `json:"pool"`;CacheResolvedAtUnixNano int64 `json:"cache_resolved_at_unix_nano"`;SuccessAddress string `json:"success_address,omitempty"`;Body string `json:"body,omitempty"`;Policy Policy `json:"policy"`;DataPlaneVerified bool `json:"data_plane_verified"`;ServiceExistence string `json:"service_existence"`}

