def plan(start,end,allocations):
 if type(start) is not int or type(end) is not int or not 1<=start<=end<=65535:raise ValueError('range')
 size=end-start+1;offset=0 if size<=16 else min(max(16,size//32),128)
 used={};uid_ports={}
 for row in allocations:
  uid=row['uid'];ports=row['ports']
  for port in ports:
   if type(port) is not int or not start<=port<=end or port in used:raise ValueError('invalid inventory')
   used[port]=uid;uid_ports.setdefault(uid,[]).append(port)
 low=list(range(start,start+offset));high=list(range(start+offset,end+1))
 return {'offset':offset,'low':low,'high':high,'remaining_low':len([p for p in low if p not in used]),'remaining_high':len([p for p in high if p not in used]),'remaining_total':size-len(used),'owners':{str(p):used[p] for p in sorted(used)}}
def allocate(request,namespace,name,node_port=None):
