 port={'name':'http','protocol':'TCP','port':80,'targetPort':8080}
 if node_port is not None:port['nodePort']=node_port
 obj={'apiVersion':'v1','kind':'Service','metadata':{'name':name},'spec':{'type':'NodePort','selector':{'app':'training'},'ports':[port]}}
