  if code==403:raise PermissionError('API read forbidden')
  if code!=200:raise RuntimeError('API read failed: '+str(code))
  return obj
 def service(self):return self.get('/api/v1/namespaces/'+quote(self.namespace,safe='')+'/services/'+quote(self.name,safe=''))
 def endpoint(self,query):return '/apis/discovery.k8s.io/v1/namespaces/'+quote(self.namespace,safe='')+'/endpointslices?'+urlencode(query)
 def owned(self,obj):return any(r.get('kind')=='Service' and r.get('uid')==self.uid for r in obj['metadata'].get('ownerReferences',[]))
 def sync(self):
  service=self.service();self.uid=service['metadata']['uid'];items={};token='';rv=None
  while True:
   query={'labelSelector':'kubernetes.io/service-name='+self.name,'limit':2}
   if token:query['continue']=token
   page=self.get(self.endpoint(query))
   if rv is None:rv=page['metadata']['resourceVersion']
   for obj in page['items']:
    if self.owned(obj):items[obj['metadata']['uid']]=obj
   token=page['metadata'].get('continue','')
   if not token:break
  self.slices=items;self.rv=rv;return self.snapshot()
 def snapshot(self):
  return sorted({address for obj in self.slices.values() for endpoint in obj.get('endpoints',[]) if endpoint.get('conditions',{}).get('ready') is not False for address in endpoint['addresses']})
 def watch_once(self):
  if self.service()['metadata']['uid']!=self.uid:return self.sync()
  query={'labelSelector':'kubernetes.io/service-name='+self.name,'watch':'true','resourceVersion':self.rv,'timeoutSeconds':1,'allowWatchBookmarks':'true'}
  code,payload=self.request('GET',self.endpoint(query))
  if code==410:return self.sync()
  if code==403:raise PermissionError('API watch forbidden')
  if code!=200:raise RuntimeError('API watch failed: '+str(code))
  events=[payload] if isinstance(payload,dict) else [json.loads(line) for line in payload.splitlines() if line.strip()]
  for event in events:
   obj=event['object'];kind=event['type']
   if kind=='ERROR':
    if obj.get('code')==410:return self.sync()
    raise RuntimeError('API watch error')
   self.rv=obj['metadata']['resourceVersion']
   if kind=='BOOKMARK':continue
   uid=obj['metadata']['uid']
   if kind=='DELETED':self.slices.pop(uid,None)
   elif kind in ('ADDED','MODIFIED'):
    if self.owned(obj):self.slices[uid]=obj
    else:self.slices.pop(uid,None)
  return self.snapshot()

