        raw=pathlib.Path('/proc',str(process.pid),'stat').read_text();parts=raw[raw.rfind(')')+2:].split()
        print('OPSF_OWNED_PID '+json.dumps({'pid':process.pid,'start_ticks':parts[19],'root':str(self.root)}),flush=True)
        try:
            ready=False
