package task
import "errors"
func ProcessOne(q NativeQueue,work func(string)error)bool{
 key,stop:=q.Get();if stop{return false};defer q.Done(key)
 err:=work(key)
 if err==nil||errors.Is(err,ErrPermanent){q.Forget(key)}else{q.AddRateLimited(key)}
 return true
}
func Rebuild(q NativeQueue,authoritativeKeys []string){for _,key:=range authoritativeKeys{q.Add(key)}}

设计映射
{"done": "end-processing-and-requeue-dirty-key", "forget": "clear-rate-limit-history", "permanent": "forget-no-retry", "queue_is_durable": false, "restart_source": "authoritative-api-and-operation-records"}
原题解释
交付队列消费状态图，区分处理占用的完成标记Done与限速器历史清理Forget。Done结束本次处理并允许期间再次变脏的键重新排队，Forget清除相关重试记录，二者不能互相替代；成功后只Done可能留下不应延续的退避历史，只Forget则可能让队列认为任务仍在处理。验收同键处理期间再次Add、连续失败后成功、永久非法输入及工作函数异常返回，检查后续事件仍可被处理且退避恢复合理。若使用controller-runtime自带协调器，应审查其既有队列责任而非重复手工调用造成双重处理。失败暂停受影响消费者并保留未决键与外部操作账目，恢复不能依赖进程内队列是持久消息；重启后必须从权威状态重新发现待协调对象。

