def set_ready(request,path,ready,reason,now,max_attempts=3):
 import copy
 if type(max_attempts) is not int or not 1<=max_attempts<=5:raise ValueError('bounded retries required')
 for _ in range(max_attempts):
  code,obj=request('GET',path)
  if code!=200:raise RuntimeError('read failed')
  status=copy.deepcopy(obj.get('status',{}));conditions=status.get('conditions',[])
  old=next((x for x in conditions if x.get('type')=='Ready'),{})
  wanted={'type':'Ready','status':'True' if ready else 'False','reason':reason,'observedGeneration':obj['metadata']['generation']}
  if all(old.get(k)==v for k,v in wanted.items()):return False
  desired={**old,**wanted};desired['lastTransitionTime']=old.get('lastTransitionTime',now) if old.get('status')==wanted['status'] else now
  status['conditions']=[x for x in conditions if x.get('type')!='Ready']+[desired]
  code,_=request('PATCH',path+'/status',{'metadata':{'resourceVersion':obj['metadata']['resourceVersion']},'status':status},content_type='application/merge-patch+json')
  if code==200:return True
  if code!=409:raise RuntimeError('status write failed')
 raise RuntimeError('conflict retry budget exhausted')


