import copy,http.server,json,ssl,threading
from task import convert
class Webhook:
 def __init__(self,c):
  self.calls=[];parent=self
  class Handler(http.server.BaseHTTPRequestHandler):
   def log_message(self,*args):pass
   def do_POST(self):
    review=json.loads(self.rfile.read(int(self.headers['Content-Length'])));r=review['request'];objects=[]
    try:
     for original in r['objects']:
      objects.append(convert(copy.deepcopy(original),r['desiredAPIVersion']))
      parent.calls.append({'source':original['apiVersion'],'target':r['desiredAPIVersion']})
     response={'uid':r['uid'],'result':{'status':'Success'},'convertedObjects':objects}
    except Exception as e:response={'uid':r['uid'],'result':{'status':'Failure','message':str(e)}}
    raw=json.dumps({'apiVersion':'apiextensions.k8s.io/v1','kind':'ConversionReview','response':response}).encode();self.send_response(200);self.send_header('Content-Type','application/json');self.send_header('Content-Length',str(len(raw)));self.end_headers();self.wfile.write(raw)
  self.server=http.server.ThreadingHTTPServer(('127.0.0.1',0),Handler);self.server.daemon_threads=True
  ctx=ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER);ctx.load_cert_chain(str(c.root/'server.crt'),str(c.root/'server.key'));self.server.socket=ctx.wrap_socket(self.server.socket,server_side=True)
  self.url='https://127.0.0.1:'+str(self.server.server_port)+'/convert';self.thread=threading.Thread(target=self.server.serve_forever,daemon=True);self.thread.start()
 def close(self):
  self.server.shutdown();self.server.server_close();self.thread.join(timeout=3)
  assert not self.thread.is_alive(),'owned conversion server thread leaked'

