 "k8s.io/apimachinery/pkg/apis/meta/v1/unstructured";"k8s.io/apimachinery/pkg/runtime/schema";"sigs.k8s.io/controller-runtime/pkg/client")
func UpgradeConversion(ctx context.Context,c client.Client,name,target string,ca []byte,probe UpgradeProbe)error{
 if name==""||target==""||len(ca)==0||probe==nil{return fmt.Errorf("explicit approved target/probe required")}
 _ = probe(ctx,target,ca)
 d:=new(apiextv1.CustomResourceDefinition);if err:=c.Get(ctx,client.ObjectKey{Name:name},d);err!=nil{return err}
 found:=false
 for i:=range d.Spec.Versions{v:=&d.Spec.Versions[i];if v.Name=="v1"{found=v.Served;v.Storage=true}else{v.Storage=false}}
 if !found{return fmt.Errorf("approved hub not served")}
 d.Spec.Conversion=&apiextv1.CustomResourceConversion{Strategy:apiextv1.WebhookConverter,Webhook:&apiextv1.WebhookConversion{ConversionReviewVersions:[]string{"v1"},ClientConfig:&apiextv1.WebhookClientConfig{URL:&target,CABundle:append([]byte{},ca...)}}}
 if err:=c.Update(ctx,d);err!=nil{return err}
 // Every object is read and PUT through the actual new storage version. A
 // status.storedVersions edit alone is never a storage migration.
 list:=new(unstructured.UnstructuredList);list.SetGroupVersionKind(schema.GroupVersionKind{Group:ConvGroup,Version:"v1",Kind:"WidgetList"})
 if err:=c.List(ctx,list);err!=nil{return err}
 for i:=range list.Items{obj:=&list.Items[i];if err:=c.Update(ctx,obj);err!=nil{return err}}
 if err:=c.Get(ctx,client.ObjectKey{Name:name},d);err!=nil{return err}
 d.Status.StoredVersions=[]string{"v1"}
 if err:=c.Status().Update(ctx,d);err!=nil{return err}
 for i:=range d.Spec.Versions{if d.Spec.Versions[i].Name=="v1alpha1"{d.Spec.Versions[i].Served=false}}
 return c.Update(ctx,d)
}

