func TestActualConversionUpgradeCompatibilityAndPhysicalStorage(t *testing.T){
 ctx:=context.Background();c:=direct(t);ns:=namespace(t,c);oldServer:=signedServer(t,conversionHandler())
 d:=conversionDefinition(oldServer.URL,caBundle(t),"v1alpha1");installConversion(t,c,d)
 alpha:=widgets(t,"v1alpha1",ns);hub:=widgets(t,"v1",ns);beta:=widgets(t,"v2beta1",ns)
 first,e:=alpha.Create(ctx,widget("v1alpha1",ns,"first",map[string]interface{}{"timeoutMilliseconds":int64(1200),"mode":"fast"}),metav1.CreateOptions{});must(t,e)
 second,e:=hub.Create(ctx,widget("v1",ns,"second",map[string]interface{}{"timeoutNanoseconds":int64(2345000000),"mode":"durable"}),metav1.CreateOptions{});must(t,e)
 storedVersion(t,ns,"first","v1alpha1");storedVersion(t,ns,"second","v1alpha1")
 before:=new(apiextv1.CustomResourceDefinition);must(t,c.Get(ctx,client.ObjectKeyFromObject(d),before))
 healthy:=signedServer(t,conversionHandler())
 if UpgradeConversion(ctx,c,d.Name,healthy.URL,[]byte("wrong-CA"),actualProbe)==nil{t.Fatal("invalid target CA accepted")}
 unchanged:=new(apiextv1.CustomResourceDefinition);must(t,c.Get(ctx,client.ObjectKeyFromObject(d),unchanged))
 if !reflect.DeepEqual(before.Spec,unchanged.Spec)||!reflect.DeepEqual(before.Status.StoredVersions,unchanged.Status.StoredVersions){t.Fatal("failed TLS preflight changed active conversion/storage")}
 // A genuine handler whose scheme lacks beta still returns ConversionReview
 // Failure, even though HTTPS and HTTP 200 work.
 incompleteScheme:=nativeScheme();incompleteScheme.AddKnownTypeWithName(schema.GroupVersionKind{Group:ConvGroup,Version:"v1",Kind:"Widget"},&HubDoc{});incompleteScheme.AddKnownTypeWithName(schema.GroupVersionKind{Group:ConvGroup,Version:"v1alpha1",Kind:"Widget"},&Alpha{})
 incomplete:=signedServer(t,whconversion.NewWebhookHandler(incompleteScheme))
 if UpgradeConversion(ctx,c,d.Name,incomplete.URL,caBundle(t),actualProbe)==nil{t.Fatal("incompatible scheme accepted")}
 must(t,c.Get(ctx,client.ObjectKeyFromObject(d),unchanged));if !reflect.DeepEqual(before.Spec,unchanged.Spec){t.Fatal("incompatible target replaced old path")}
 if _,e=alpha.Get(ctx,"first",metav1.GetOptions{});e!=nil{t.Fatal("old API path was removed before successful preflight",e)}
 must(t,UpgradeConversion(ctx,c,d.Name,healthy.URL,caBundle(t),actualProbe))
 storedVersion(t,ns,"first","v1");storedVersion(t,ns,"second","v1")
 live:=new(apiextv1.CustomResourceDefinition);must(t,c.Get(ctx,client.ObjectKeyFromObject(d),live))
