 oldServer.Close()
 a,e:=hub.Get(ctx,"first",metav1.GetOptions{});must(t,e);b,e:=beta.Get(ctx,"second",metav1.GetOptions{});must(t,e)
 if a.GetUID()!=first.GetUID()||b.GetUID()!=second.GetUID()||getInt(t,a,"spec","timeoutNanoseconds")!=1200000000||getString(t,b,"spec","timeoutSeconds")!="2.345"{t.Fatal("physical migration lost native data")}
