package task
import("fmt";"math";"math/big";"strconv";"strings";metav1 "k8s.io/apimachinery/pkg/apis/meta/v1")
func AlphaToHub(a *Alpha,h *HubDoc)error{
 if a.Spec.TimeoutMilliseconds<0||a.Spec.TimeoutMilliseconds>math.MaxInt64/1000000{return fmt.Errorf("millisecond range overflow")}
 h.ObjectMeta=*a.ObjectMeta.DeepCopy();h.TypeMeta=metav1.TypeMeta{APIVersion:ConvGroup+"/v1",Kind:"Widget"}
 h.Spec=HubSpec{TimeoutNanoseconds:a.Spec.TimeoutMilliseconds*1000000,Mode:a.Spec.Mode};return nil
}
func HubToAlpha(h *HubDoc,a *Alpha)error{
 if h.Spec.TimeoutNanoseconds<0||h.Spec.TimeoutNanoseconds%1000000!=0{return fmt.Errorf("cannot represent hub value in milliseconds")}
 a.ObjectMeta=*h.ObjectMeta.DeepCopy();a.TypeMeta=metav1.TypeMeta{APIVersion:ConvGroup+"/v1alpha1",Kind:"Widget"};a.Spec=AlphaSpec{TimeoutMilliseconds:h.Spec.TimeoutNanoseconds/1000000,Mode:h.Spec.Mode};return nil
}
func BetaToHub(b *Beta,h *HubDoc)error{
 value,ok:=new(big.Rat).SetString(b.Spec.TimeoutSeconds);if !ok||value.Sign()<0{return fmt.Errorf("invalid decimal seconds")}
 value.Mul(value,big.NewRat(1000000000,1))
 if !value.IsInt()||!value.Num().IsInt64()||value.Num().Int64()%1000000!=0{return fmt.Errorf("precision or range not supported by all served versions")}
 h.ObjectMeta=*b.ObjectMeta.DeepCopy();h.TypeMeta=metav1.TypeMeta{APIVersion:ConvGroup+"/v1",Kind:"Widget"};h.Spec=HubSpec{TimeoutNanoseconds:value.Num().Int64(),Mode:b.Spec.Mode};return nil
}
func HubToBeta(h *HubDoc,b *Beta)error{
 if h.Spec.TimeoutNanoseconds<0||h.Spec.TimeoutNanoseconds%1000000!=0{return fmt.Errorf("hub precision not supported by legacy spoke")}
 value:=strconv.FormatInt(h.Spec.TimeoutNanoseconds/1000000000,10);fraction:=h.Spec.TimeoutNanoseconds%1000000000
 if fraction!=0{value+="."+strings.TrimRight(fmt.Sprintf("%09d",fraction),"0")}
 b.ObjectMeta=*h.ObjectMeta.DeepCopy();b.TypeMeta=metav1.TypeMeta{APIVersion:ConvGroup+"/v2beta1",Kind:"Widget"};b.Spec=BetaSpec{TimeoutSeconds:value,Mode:h.Spec.Mode};return nil
}

