package task
import("bytes";"context";"crypto/tls";"crypto/x509";"encoding/base64";"encoding/json";"fmt";"io";"net/http";"os";"strings";"testing";"time"
 apiextv1 "k8s.io/apiextensions-apiserver/pkg/apis/apiextensions/v1";metav1 "k8s.io/apimachinery/pkg/apis/meta/v1";"k8s.io/apimachinery/pkg/runtime";"k8s.io/apimachinery/pkg/types")
func actualProbe(ctx context.Context,url string,ca []byte)error{
 roots:=x509.NewCertPool();if !roots.AppendCertsFromPEM(ca){return fmt.Errorf("target CA invalid")}
 httpClient:=&http.Client{Timeout:2*time.Second,Transport:&http.Transport{TLSClientConfig:&tls.Config{RootCAs:roots,MinVersion:tls.VersionTLS12}}}
 // Probe both spoke directions on the genuine controller-runtime HTTPS
 // handler. HTTP 200 with ConversionReview Failure is not healthy.
 for _,desired:=range []string{"v1alpha1","v2beta1"}{
  raw:=[]byte(`{"apiVersion":"convert.s05.example/v1","kind":"Widget","metadata":{"name":"probe","namespace":"training"},"spec":{"timeoutNanoseconds":1200000000,"mode":"fast"}}`)
  review:=apiextv1.ConversionReview{TypeMeta:metav1.TypeMeta{APIVersion:"apiextensions.k8s.io/v1",Kind:"ConversionReview"},Request:&apiextv1.ConversionRequest{UID:types.UID("probe-"+desired),DesiredAPIVersion:ConvGroup+"/"+desired,Objects:[]runtime.RawExtension{{Raw:raw}}}}
  body,_:=json.Marshal(review);req,e:=http.NewRequestWithContext(ctx,"POST",url,bytes.NewReader(body));if e!=nil{return e};req.Header.Set("Content-Type","application/json")
  response,e:=httpClient.Do(req);if e!=nil{return e};data,e:=io.ReadAll(response.Body);response.Body.Close();if e!=nil{return e};if response.StatusCode!=200{return fmt.Errorf("target HTTP status %d",response.StatusCode)}
  decoded:=new(apiextv1.ConversionReview);if e=json.Unmarshal(data,decoded);e!=nil{return e}
  if decoded.Response==nil||decoded.Response.UID!=review.Request.UID||decoded.Response.Result.Status!=metav1.StatusSuccess||len(decoded.Response.ConvertedObjects)!=1{return fmt.Errorf("target cannot safely convert %s",desired)}
 }
 return nil
}
func storedVersion(t *testing.T,ns,name,want string){
