package task
import("context";"fmt";"net/http"
 corev1 "k8s.io/api/core/v1";"golang.org/x/time/rate";"sigs.k8s.io/controller-runtime/pkg/client")
func SecretIndex(obj client.Object)[]string{
 a,ok:=obj.(*WorkApp);if !ok||a==nil||a.Spec.SecretRef==""{return nil};return []string{a.Spec.SecretRef}
}
func DependentKeys(ctx context.Context,r client.Reader,secret *corev1.Secret)([]client.ObjectKey,error){
 list:=new(WorkAppList);if err:=r.List(ctx,list,client.InNamespace(secret.Namespace),client.MatchingFields{"spec.secretRef":secret.Name});err!=nil{return nil,err}
 keys:=[]client.ObjectKey{};for i:=range list.Items{a:=&list.Items[i];if a.Namespace==secret.Namespace&&a.Spec.SecretRef==secret.Name{keys=append(keys,client.ObjectKeyFromObject(a))}};return keys,nil
}
func Settings()(int,rate.Limit,int){return 4,50,1}
func ReconcileSecret(ctx context.Context,c client.Client,key client.ObjectKey,httpClient *http.Client,url string,limiter *rate.Limiter)error{
 a:=new(WorkApp);if e:=c.Get(ctx,key,a);e!=nil{return e}
 secret:=new(corev1.Secret);if e:=c.Get(ctx,client.ObjectKey{Namespace:a.Namespace,Name:a.Spec.SecretRef},secret);e!=nil{return e}
 request,e:=http.NewRequestWithContext(ctx,"POST",url,nil);if e!=nil{return e};request.Header.Set("Authorization","Bearer "+string(secret.Data["token"]))
 if e=limiter.Wait(ctx);e!=nil{return e}
 response,e:=httpClient.Do(request);if e!=nil{return e};response.Body.Close()
 if response.StatusCode!=200{return fmt.Errorf("downstream status %d",response.StatusCode)}
 a.Status.SecretVersion=secret.ResourceVersion;a.Status.ObservedGeneration=a.Generation
 return c.Status().Update(ctx,a)
}

