func Measure(reg prometheus.Registerer,observations []Observation,now time.Time,objective time.Duration)(SLOReport,error){
 report:=SLOReport{ErrorsByClass:map[string]int{}}
 if objective<=0{return report,fmt.Errorf("positive objective required")}
 latest:=map[string]Observation{}
 for _,o:=range observations{k:=string(o.UID);old,ok:=latest[k];if !ok||o.DesiredGeneration>old.DesiredGeneration||o.DesiredGeneration==old.DesiredGeneration&&o.Confirmed.After(old.Confirmed){latest[k]=o}}
 scale:="small";if len(latest)>25{scale="medium"};if len(latest)>250{scale="large"}
 durations:=prometheus.NewHistogramVec(prometheus.HistogramOpts{Name:"s05_convergence_seconds",Help:"Desired generation submission to native API confirmation",Buckets:[]float64{.05,.2,1,5,30}},[]string{"scenario","scale"})
 pending:=prometheus.NewGaugeVec(prometheus.GaugeOpts{Name:"s05_pending",Help:"Unconfirmed current desired generations"},[]string{"scenario","scale"})
 failures:=prometheus.NewCounterVec(prometheus.CounterOpts{Name:"s05_failures_total",Help:"Observed native attempt failure classes"},[]string{"class","scale"})
 misoperations:=prometheus.NewCounter(prometheus.CounterOpts{Name:"s05_misoperations_total",Help:"Invalid generation or confirmation invariants"})
 reg.MustRegister(durations,pending,failures,misoperations)
 for _,o:=range latest{
  report.Desired++;scenario:=o.Scenario
  switch scenario{case "normal","slow","storm","failover","permission","stale","misoperation":default:scenario="other"}
  for class,count:=range o.Failures{if count<=0{continue};switch class{case "transient","permission","conflict","canceled":default:class="other"};report.ErrorsByClass[class]+=count;failures.WithLabelValues(class,scale).Add(float64(count))}
  if o.UID==""||o.DesiredGeneration<=0||o.ObservedGeneration>o.DesiredGeneration||o.ObservedGeneration==o.DesiredGeneration&&!o.Confirmed.IsZero()&&o.Confirmed.Before(o.Submitted){report.Misoperations++;misoperations.Inc();continue}
  if !o.Ready||o.ObservedGeneration!=o.DesiredGeneration||o.Confirmed.IsZero(){
   report.Pending++;pending.WithLabelValues(scenario,scale).Inc();age:=now.Sub(o.Submitted).Seconds();if age>report.MaxPendingAgeSeconds{report.MaxPendingAgeSeconds=age};continue
  }
  latency:=o.Confirmed.Sub(o.Submitted);report.Converged++;durations.WithLabelValues(scenario,scale).Observe(latency.Seconds());if latency<=objective{report.WithinObjective++}
 }
 if report.Desired>0{report.Ratio=float64(report.WithinObjective)/float64(report.Desired)}
 return report,nil
}

