	r, c := setup(t, sample())
	reconcile(t, r)
	a := &WebApp{}
	get(t, c, a)
	a.Spec.Replicas = 4
	a.Generation = 2
	if err := c.Update(ctx, a); err != nil {
		t.Fatal(err)
	}
	wrapped := &onceConflict{Client: c, remaining: 1}
	r.Client = wrapped
	reconcile(t, r)
	dep := &appsv1.Deployment{}
	get(t, c, dep)
	if wrapped.attempts != 2 || *dep.Spec.Replicas != 4 {
		t.Fatalf("conflict not retried: %d", wrapped.attempts)
	}
}
