package task
import("database/sql";"k8s.io/apimachinery/pkg/runtime/schema";"sigs.k8s.io/controller-runtime/pkg/client")
var jobGVK=schema.GroupVersionKind{Group:"batch006.opsforge.invalid",Version:"v1",Kind:"EventJob"}
// JobsReconciler coordinates the actual EventJob CR with native MySQL EVENTs.
// operations is durable controller intent; started/results are committed by the
// real MySQL scheduler itself and survive controller restart. Never fabricate
// a cloud job reply or treat DROP EVENT as cancellation of already-running SQL.
type JobsReconciler struct{K client.Client;SQL *sql.DB}

