CREATE DATABASE nativejobs;
CREATE TABLE nativejobs.operations(op_id VARCHAR(64) PRIMARY KEY, owner_uid VARCHAR(64) NOT NULL, generation BIGINT NOT NULL, spec_digest VARCHAR(64) NOT NULL, target_value TEXT NOT NULL, submitted_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP(6), state VARCHAR(40) NOT NULL);
CREATE TABLE nativejobs.started(op_id VARCHAR(64) PRIMARY KEY, started_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP(6));
CREATE TABLE nativejobs.results(op_id VARCHAR(64) PRIMARY KEY, result_value TEXT NOT NULL, completed_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP(6));
CREATE USER 'nativejobs'@'localhost' IDENTIFIED BY 'private-event-password';
GRANT SELECT,INSERT,UPDATE,EVENT ON nativejobs.* TO 'nativejobs'@'localhost';

