func jSet(t *testing.T,c client.Client,key client.ObjectKey,value string){t.Helper();u:=b6Get(t,c,key,jobGVK);_=unstructured.SetNestedField(u.Object,value,"spec","value");b6Must(t,c.Update(context.Background(),u))}
func jWait(t *testing.T,f func()bool){t.Helper();until:=time.Now().Add(10*time.Second);for time.Now().Before(until){if f(){return};time.Sleep(15*time.Millisecond)};t.Fatal("native scheduler/controller result did not converge")}

